def solve(di, marks):
    H,W=len(di),len(di[0])
    maj=max(set(x for r in di for x in r), key=lambda c: sum(r.count(c) for r in di))
    out=[[maj]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if di[i][j]==marks: continue
            for di2 in range(max(0,i-1),min(H,i+2)):
                for dj in range(max(0,j-1),min(W,j+2)):
                    out[di2][dj]=1
    return out
